async function sourceOperation(action: "create" | "remove", root?: string) {
  return new Promise<string>((accept, reject) => {
    const child = spawn(
      resolve(process.env.SystemRoot ?? "C:/Windows", "System32/wsl.exe"),
      [
        "-d",
        "Ubuntu",
        "--exec",
        "/usr/bin/python3",
        "-I",
        `${linuxWorkspace}/tests/helpers/coding-composition-source.py`,
        action,
        ...(root ? [root] : []),
      ],
      { env: { SystemRoot: process.env.SystemRoot }, windowsHide: true },
    );
    let output = "",
      errors = "";
    child.stdout?.on("data", (chunk) => {
      output += String(chunk);
    });
    child.stderr?.on("data", (chunk) => {
      errors += String(chunk);
    });
    child.once("error", reject);
    child.once("close", (code) =>
      code === 0
        ? accept(output.trim())
        : reject(new Error(`Synthetic source operation failed: ${errors.slice(-512)}`)),
    );
    child.stdin?.end();
  });
}

