async function admitActual() {
  if (!fixture || !source) throw new Error("Native composition fixture not prepared");
  expect(
    provider.qualified,
    "Actual provider readiness must qualify before Foundation admission",
  ).toBe(true);
  const preparation = await engine.coding.prepare(
    fixture.freshOwner(),
    {
      ...fixture.input,
      input: "Change answer.cjs to export 42 and run its Node test. Report the result.",
      runner: selectedRunner,
      commitSha: source.commitSha,
      limits: { ...fixture.input.limits, timeoutSeconds: 300, maxCostMicros: 1000000 },
      testProfile: "test",
    },
    randomUUID(),
  );
  const task = await engine.coding.admit(
    fixture.freshOwner(),
    { preparationId: preparation.id, expectedHash: preparation.hash },
    randomUUID(),
  );
  activeTaskId = task.id;
  return { preparation, task };
}

